import type { MetadataRoute } from "next";

/**
 * Web app manifest. The icons are generated by the `pwa-icon/[size]` route
 * rather than committed as binaries, so the brand mark stays in one place and
 * there is no PNG drift between the tab icon and the install icon.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "InterviewOS — Practice your interview before the real one",
    short_name: "InterviewOS",
    description:
      "Practice realistic, role-specific interview questions with AI feedback and spoken mock interviews.",
    id: "/",
    start_url: "/",
    scope: "/",
    display: "standalone",
    background_color: "#fbfcfe",
    theme_color: "#fbfcfe",
    categories: ["education", "productivity"],
    icons: [
      {
        src: "/pwa-icon/192",
        sizes: "192x192",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/pwa-icon/512",
        sizes: "512x512",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/pwa-icon/maskable-512",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
  };
}
